#include <Arduino.h>

void setup() {
  pinMode(13, OUTPUT);
  digitalWrite(13, LOW);
  Serial.begin(9600);
  Serial.println("UNO_RX_BOOT");
}

void loop() {
  while (Serial.available() > 0) {
    const int c = Serial.read();
    if (c == '1') {
      digitalWrite(13, !digitalRead(13));
      Serial.write('K');
      Serial.println("PU_UNO_RX");
    }
  }
}
